parameters.message:
=
{{ (() => {
  const agent = $('02 - AI Agent | Atención comercial').first().json;
  const steps = agent.intermediateSteps ?? [];

  const tools = steps
    .map(step => step.action?.tool)
    .filter(Boolean);

  const hasToolError = steps.some(step => {
    const observation = step.observation;
    if (!observation) return false;

    try {
      const data = typeof observation === 'string'
        ? JSON.parse(observation)
        : observation;

      return Array.isArray(data)
        ? data.some(item => item?.error)
        : Boolean(data?.error);
    } catch {
      return false;
    }
  });

  const status = hasToolError
    ? 'TOOL_ERROR'
    : tools.length > 0
      ? 'SUCCESS'
      : 'NO_TOOL_USED';

  return `CENTRO ALMA MISTICA
REPORTE DE SUPERVISION - CHECKPOINT 1

Execution ID: ${$execution.id}
Workflow: ${$workflow.name}

ESTADO DE LA EJECUCION
${status}

HERRAMIENTAS UTILIZADAS
${tools.length > 0 ? tools.join(', ') : 'Sin llamada registrada'}

CANTIDAD DE PASOS INTERMEDIOS
${steps.length}

RESPUESTA DEL AGENTE
${(agent.output ?? '').replace(/\*\*/g, '')}

---
Reporte automatico de laboratorio.
No confirma reservas, pagos ni inscripciones.`;
})() }}
